'use strict';
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let courses,progress;
function showPlan(id){const w=courses.weeks.find(x=>x.id===id);$('plan-title').textContent=`Week 0${w.id} · 这一周怎么学`;$('plan-description').textContent=w.plan;$('day-plan').innerHTML=w.days.map((d,i)=>`<a class="day-card" href="practice.html?week=${w.id}&day=${i+1}"><small>DAY 0${i+1}</small><strong>${esc(d.short)}</strong><span>${d.tasks.filter(t=>progress.passed?.[t]).length} / ${d.tasks.length} 已完成</span></a>`).join('')}
async function init(){try{const responses=await Promise.all([fetch('/courses.json',{cache:'no-store'}),fetch('/api/state',{cache:'no-store'})]);if(responses.some(r=>!r.ok))throw Error();[courses,progress]=await Promise.all(responses.map(r=>r.json()));let total=0,completed=0;let next=null;for(const w of courses.weeks){const ids=w.days.flatMap(d=>d.tasks);w.done=ids.filter(id=>progress.passed?.[id]).length;total+=w.done;if(w.done===ids.length)completed++;if(!next&&w.done<ids.length){let day=w.days.findIndex(d=>d.tasks.some(t=>!progress.passed?.[t]));let task=w.days[day].tasks.findIndex(t=>!progress.passed?.[t]);next={w,day,task}}}$('total-done').innerHTML=`${total}<small> / 42</small>`;$('weeks-done').innerHTML=`0${completed}<small> / 02</small>`;$('week-cards').innerHTML=courses.weeks.map(w=>`<article class="week-card"><div class="card-top"><span class="card-kicker">WEEK 0${w.id} / ${esc(w.tag)}</span><span class="badge ${w.done===21?'':'in-progress'}">${w.done===21?'已完成':w.done?'进行中':'可开始'}</span></div><div class="card-body"><div class="card-title-row"><h3>${esc(w.title)}</h3><span class="week-number" aria-hidden="true">0${w.id}</span></div><p>${esc(w.description)}</p><div class="tags">${w.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div><div class="card-progress"><span>7 天 · 21 道练习</span><b>${w.done} / 21</b></div><div class="track" role="progressbar" aria-label="第 ${w.id} 周进度" aria-valuenow="${w.done}" aria-valuemin="0" aria-valuemax="21"><div style="width:${w.done/21*100}%"></div></div><div class="card-actions"><a class="open-week ${w.done===21?'complete-link':''}" href="practice.html?week=${w.id}">${w.done===21?'回顾与重练':w.done?'继续本周':'进入本周'} <span>↗</span></a><button class="preview-button" data-week="${w.id}">查看七天安排 ↓</button></div></div></article>`).join('');document.querySelectorAll('[data-week]').forEach(button=>button.onclick=()=>{showPlan(Number(button.dataset.week));$('plan-title').scrollIntoView({behavior:'smooth',block:'center'})});if(next){$('continue-label').textContent=next.w.id===2&&courses.weeks[0].done===21?'Week 01 已完成 · 新一周已就绪':'下一个练习';$('continue-title').textContent=`Week 0${next.w.id} · Day 0${next.day+1} · ${next.w.days[next.day].short}`;$('continue-description').textContent=next.w.plan;$('continue-link').href=`practice.html?week=${next.w.id}&day=${next.day+1}&task=${next.task+1}`;$('continue-link').textContent=next.w.done?'继续练习 →':'开始新一周 →'}else{$('continue-label').textContent='两周训练已全部完成';$('continue-title').textContent='重新挑战，或试一个自己的想法。';$('continue-description').textContent='在自由练习场组合学过的方法。';$('continue-link').textContent='进入自由练习 →';$('continue-link').href='practice.html?week=2&free=1'}showPlan(2);
if(document.modelContext?.registerTool){
  document.modelContext.registerTool({
    name:'read_week_overview',description:'读取两周课程及其完成数量。',
    inputSchema:{type:'object',properties:{},additionalProperties:false},
    annotations:{readOnlyHint:true},
    execute:async()=>({weeks:courses.weeks.map(w=>({week:w.id,title:w.title,completed:w.done,total:21}))})
  });
}
}catch{$('week-cards').innerHTML='<p class="error">课程暂时未加载。请重新双击启动脚本，再刷新这个页面。</p>'}}
init();window.addEventListener('pageshow',e=>{if(e.persisted)location.reload()});
